function applicationProfile(id){return APPLICATION_PROFILES.find(p=>p.id===id)}
function profileResume(id){
const p=applicationProfile(id);if(!p)return resume();
const blocks=p.order.map(id=>RESUME_FACTS[id]);
return `<section class="page-head"><div class="eyebrow">RESUME · ${esc(p.role)}</div><h1>윤준명 <span style="font-size:.4em;color:var(--muted)">/ newbission</span></h1><p>${esc(p.summary)}</p><div class="print-label">GitHub: https://github.com/newbission<br>Portfolio: https://newbission.github.io/portfolio/</div><div class="actions"><button class="btn dark" id="print-resume">인쇄 / PDF 저장 <span>↓</span></button><a class="textlink" href="#portfolio">포트폴리오 보기 →</a></div></section><div class="resume-layout"><aside class="resume-aside"><p>주요 경험<br>경력 이력<br>기술·교육</p></aside><div class="resume-main"><section><h2>주요 경험</h2>${blocks.map(f=>`<h3>${esc(f.title)}</h3><p class="date">${esc(f.company)} · ${esc(f.date)}</p><ul>${f.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>`).join('')}</section><section><h2>경력 이력</h2><h3>매장 운영 시스템 프로젝트</h3><p>2026.02–현재 · 프리랜서 · 업무 시스템 설계·운영</p><h3>AI 서비스 개발 프로젝트</h3><p>2025.06–2026.02 · 계약직 · AI·API 개발</p><h3>백엔드 교육 과정</h3><p>2025.02–2025.06 · 프리랜서 강사 · 9기·11기 Python 백엔드 보충 강의<br>2024.08–2025.01 · 계약직 조교 · 수업·학습 자료·질의응답 지원</p></section><section><h2>기술과 활용 범위</h2><p>AWS EC2·RDS·S3·CloudFront·IAM·ALB, GitHub Actions: 배포·운영<br>Python·YOLO·군중 모델, RTSP·Kafka·Redis: 영상 처리와 결과 연계<br>Node.js·Nginx·Certbot: AI API와 HTTPS 배포<br>WinForms·HTML·ChatGPT API: 조회 도구와 보고서</p><h4>AI 개발 도구와 제품 기능</h4><p>근태·채용 관리 시스템에서는 주요 설계·운영 판단을 담당하고 코드 구현에 Claude Code를 활용했습니다. 오토라벨링 당시에는 Claude 웹과 모듈별 실행·디버깅을 병행했습니다. 영상 분석, 문서·음성 AI API, ChatGPT API 보고서는 제품 기능으로 연결했습니다.</p></section><section><h2>학력·교육·자격</h2><h4>명지전문대학 컴퓨터공학과</h4><p>2020.03–2023.02 · 전문학사 졸업</p><h4>Python(Django) 백엔드 온라인 부트캠프</h4><p>2024.06 수료 · 프론트엔드·기획 협업 프로젝트 2회</p><p>SQLD · 2023.10 / 정보처리산업기사 · 2023.09</p></section></div></div>`}
